#!/usr/bin/env python3
"""csvq - filter, select and sort CSV files."""
import csv
import re
import sys

USAGE = ("usage: csvq [--where COL=VALUE]... [--select COL,COL,...] "
         "[--sort COL [--numeric] [--desc]] FILE")
NUM_RE = re.compile(r'^\s*[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?\s*$')


def die(msg, code=2):
    sys.stderr.write("csvq: %s\n" % msg)
    sys.exit(code)


def parse_args(argv):
    wheres, select, sort, numeric, desc, files = [], None, None, False, False, []
    i = 0
    def value(opt):
        nonlocal i
        if i + 1 >= len(argv):
            die("option %s requires an argument\n%s" % (opt, USAGE))
        i += 1
        return argv[i]
    while i < len(argv):
        a = argv[i]
        if a == "--":
            files.extend(argv[i + 1:]); break
        if a.startswith("--") and "=" in a and a.split("=", 1)[0] in ("--where", "--select", "--sort"):
            opt, val = a.split("=", 1)
            argv = argv[:i] + [opt, val] + argv[i + 1:]
            continue
        if a == "--where":
            v = value(a)
            if "=" not in v:
                die("--where expects COL=VALUE, got: %s" % v)
            wheres.append(tuple(v.split("=", 1)))
        elif a == "--select":
            select = value(a).split(",")
        elif a == "--sort":
            sort = value(a)
        elif a == "--numeric":
            numeric = True
        elif a == "--desc":
            desc = True
        elif a in ("-h", "--help"):
            print(USAGE); sys.exit(0)
        elif a.startswith("-") and a != "-":
            die("unknown option: %s\n%s" % (a, USAGE))
        else:
            files.append(a)
        i += 1
    if len(files) != 1:
        die("expected exactly one FILE\n" + USAGE)
    return wheres, select, sort, numeric, desc, files[0]


def to_num(s):
    if NUM_RE.match(s):
        return float(s)
    return None


def main(argv):
    wheres, select, sort, numeric, desc, path = parse_args(argv)
    try:
        if path == "-":
            f = open(sys.stdin.fileno(), "r", encoding="utf-8-sig", newline="", closefd=False)
        else:
            f = open(path, "r", encoding="utf-8-sig", newline="")
        with f:
            rows = list(csv.reader(f))
    except OSError as e:
        die("cannot read %s: %s" % (path, e.strerror or e), 1)
    if not rows:
        die("empty file (no header): %s" % path, 1)
    header, data = rows[0], rows[1:]
    idx = {}
    for n, h in enumerate(header):
        idx.setdefault(h, n)

    names = [c for c, _ in wheres] + (select or []) + ([sort] if sort is not None else [])
    for c in names:
        if c not in idx:
            die("unknown column: %s" % c)

    def get(row, col):
        j = idx[col]
        return row[j] if j < len(row) else ""

    data = [r for r in data if all(get(r, c) == v for c, v in wheres)]

    if sort is not None:
        if numeric:
            nums, rest = [], []
            for r in data:
                x = to_num(get(r, sort))
                (rest if x is None else nums).append((x, r))
            nums.sort(key=lambda t: t[0], reverse=desc)  # stable either way
            data = [r for _, r in nums] + [r for _, r in rest]
        else:
            data.sort(key=lambda r: get(r, sort), reverse=desc)

    cols = select if select is not None else header
    out = csv.writer(sys.stdout, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    out.writerow(cols)
    for r in data:
        out.writerow([get(r, c) for c in cols])


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(newline="")
    except Exception:
        pass
    try:
        main(sys.argv[1:])
    except BrokenPipeError:
        sys.exit(1)
